import{_ as f,a0 as o,w as l,s as a,ao as s,I as r,x as t,a1 as p,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"diff -u: 內核開發裏的新鮮事兒 | LCTT x X-CMD","titleTemplate":false,"description":"diff -u: 內核開發裏的新鮮事兒 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"diff -u: 內核開發裏的新鮮事兒 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"diff -u: 內核開發裏的新鮮事兒 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140724 diff -u--What is New in Kernel Development","title":"diff -u: 內核開發裏的新鮮事兒","tag":"201409","desc":""},"relativePath":"201409/20140724 diff -u--What is New in Kernel Development.md","filePath":"[post].md"}'),u={name:"201409/20140724 diff -u--What is New in Kernel Development.md"};function m(d,e,C,w,T,P){const n=o("Link");return l(),a("div",null,[e[13]||(e[13]=s('<h1 id="diff-u-內核開發裏的新鮮事兒" tabindex="-1">diff -u: 內核開發裏的新鮮事兒 <a class="header-anchor" href="#diff-u-內核開發裏的新鮮事兒" aria-label="Permalink to “diff -u: 內核開發裏的新鮮事兒”">​</a></h1><p>偶爾總會有人指出Linux中的POSIX違規（violation），通常的回答是“修復違規問題”，但有時李納斯·託瓦茲認為POSIX特性是不完整的，至少他們維護Linux特性的情形下是這樣的。因此，他們或許應該構建一層POSIX兼容層，即便這個分層會相對較慢和低效。</p><p>這一次，<em>邁克爾·凱利斯克（Michael Kerrisk）</em>報告了一個影響文件操作的POSIX違規。顯然，在多線程操作期間讀寫文件會導致競爭出現，重寫其它操作的改變。</p><p>關於這是否是POSIX的一個違規存在一些討論，但到最後又有誰關心呢？數據重寫（clobbering）是很糟糕的事情。在邁克爾提交部分代碼去重現這個問題後，討論的問題集中到該做什麼去修復它。但邁克爾的觀點是：“Linux從早期開始就與UNIX不一致。（如在1992年版的史蒂夫的APUE的191頁討論到fork()操作後在父進程與子進程之間文件偏移量的共享問題。儘管史蒂夫沒有顯式地講清楚一致性的保證，但缺乏這個保證的推論這裏的討論可能有些沒意義。）”</p><p>艾爾·維洛（Al Viro）和李納斯一起設法解決這個修復。李納斯嘗試引入一個簡單的互斥量去鎖住文件，以便寫操作無法互相重寫。艾爾提出了自己的改進以改善李納斯的補丁。</p><p>李納斯一度解釋過這個故障自身的歷史。顯然，從前這個用來告訴系統去哪裏寫文件的文件指針已經被鎖在一個信號量中，所以只有一個進程可以在某一時刻對這個文件做任何操作。但是，他們從中拿走了這個信號量，以便在任何時候可以適應設備文件和其它非常規文件，因為當用户被禁止寫入其中時它們就會陷入競爭狀態。</p><p>這就是錯誤的由來。那個時候，它悄悄地通過了檢查，未被發現。因為實際上對常規文件的讀寫仍然由內核自動處理。只有文件指針自身可以避免同步。而且，因為高速線程化的文件操作是一個非常罕見的需求，所以對任何人來説都需要很長時間才能遇到這個問題並報告它。</p><p>一個有趣的小細節是當李納斯和艾爾在尋找一個修復方案時，艾爾一度抱怨李納斯採用的方法並不能支持一些確定的架構，包括<em>ARM</em>和<em>PowerPC</em>。李納斯的回應是“我懷疑關心這個是否有意義。[...]如果使用ARM/PPC架構的人停止抱怨，他們可以往gcc中加入struct-return的支持。”</p><p>看到這些問題突然產生並得到處理通常是很有趣的。在某些情況下，這個修復的部分工作必須在內核中進行，部分在GCC中，部分在其它地方。在這個特例裏，艾爾認為整個事情都應該在內核裏處理，他在靈感的激發下往補丁中寫入了自己的版本，李納斯也接受了。</p><p><em>安迪·克倫（Andi Kleen）</em>則想為<em>perf</em>增加底層CPU事件支持。問題在於這可能會導致大量的底層事件，而且會因CPU的變化而改變。即使為了所有類型的CPU把可能的時間都存儲在內存裏，也可能會顯著地增加內核的運行大小。因此，把這個信息硬編碼進內核的方法是有問題的。</p><p>他也指出<em>OProfile</em>工具依賴於這些時間的公開可用列表，儘管他表示OProfile開發者並非總維持他們的列表與最新的可用版本一致。</p><p>為了解決這些問題，安迪提交了一個補丁，允許perf識別在給定的系統上為特定的CPU需要那種事件列表，並自動從起始位置下載這個列表的最新版本。然後perf可以解釋這個列表並分析其中的事件，不會使內核負載過重。</p><p>有各種各樣對安迪代碼的反饋，其中大部分涉及到應該在哪個目錄下保存事件列表和文件如何命名。這份代碼本身的特性似乎得到了很好的回應。一處細節證明了安迪的代碼比其他人的更有爭議，就是將列表下載到用户家目錄下的一個子目錄。安迪表示如果不這樣做的話，用户可能會以系統管理員的身份去下載事件列表，這會是危害安全的操作。</p><p>薩沙·萊文（Sasha Levin）最近發佈了一個腳本來從堆棧轉儲中把<em>十六進制的偏移量</em>翻譯成有意義的指向內核源碼文件的行號。因此諸如“ffffffff811f0ec8”形式的十六進制表示可以被翻譯成“fs/proc/generic.c:445”。</p><p>然而，結果表明李納斯·託瓦茲正打算從堆棧轉儲中移除十六進制偏移量，具體原因是他們難以理解。所以薩沙的代碼看起來過時了。[譯者注：程序媛，傷不起！:&lt; ]</p><p>他們在這個問題上糾結了一番。起初，薩沙打算依賴存儲在System.map文件裏的數據區補償，但李納斯指出包括他在內的有些人並不會保留System.map文件。李納斯推薦使用/usr/bin/nm從編譯好的內核文件中提取符號表。</p><p>所以，似乎薩沙的腳本可能確實為調試堆棧轉儲提供了有意義的文件和行號，假設堆棧轉儲提供足夠的信息去完成計算。</p><hr>',18)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),p(n,{href:"http://www.linuxjournal.com/content/diff-u-whats-new-kernel-development-0"},{default:i(()=>[...e[0]||(e[0]=[t("http://www.linuxjournal.com/content/diff-u-whats-new-kernel-development-0",-1)])]),_:1})]),r("p",null,[e[3]||(e[3]=t("原文作者：",-1)),p(n,{href:"http://www.linuxjournal.com/user/801501"},{default:i(()=>[...e[2]||(e[2]=[t("Zack Brown",-1)])]),_:1})]),r("p",null,[e[6]||(e[6]=t("譯者：",-1)),p(n,{href:"https://github.com/KayGuoWhu"},{default:i(()=>[...e[4]||(e[4]=[t("KayGuoWhu",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const v=f(u,[["render",m]]);export{S as __pageData,v as default};
